railroad-beta
        title "Simple Expression"
        expression = sequence(
            nonterminal("term"),
            zeroOrMore(sequence(
                choice(terminal("+"), terminal("-")),
                nonterminal("term")
            ))
        ) ;
        term = sequence(
            nonterminal("factor"),
            zeroOrMore(sequence(
                choice(terminal("*"), terminal("/")),
                nonterminal("factor")
            ))
        ) ;
        factor = choice(
            nonterminal("number"),
            sequence(terminal("("), nonterminal("expression"), terminal(")"))
        ) ;
        number = oneOrMore(nonterminal("digit")) ;
